"""Signs and actual row/column layouts for early grades."""
def author(E,C,O,A,D,P,panel):
 E('plan-G1-media-01','S2','어느 표지를 보면 될까',
 '가상 어린이 쉼터에 붙인 표지 두 장이에요. 그림과 아래의 말을 함께 보세요.',
 '그림에 관습적으로 정해진 뜻을 외웠는지보다 이 자료에 함께 적힌 말을 연결한다. 실제 기관 표지로 소개하지 않는다.',[
 A('explanation','물을 마시려면 어느 표지가 있는 곳으로 가면 될까요? 표지의 말과 그림을 함께 짚으세요.','나 표지가 있는 곳. 물잔 그림과 이곳에서 물을 마셔요라는 말이 있다.',P(2,'rule'),[D('표지 선택','물 마시는 곳인 나를 고른다.','물잔만 짚고 어느 표지인지 밝히지 못한다.','가를 물 마시는 곳으로 고른다.'),D('그림·말 연결','물잔 그림과 물 마시라는 말을 함께 연결한다.','말이나 그림 하나만 짚는다.','작은 목소리라는 말을 물 마시기로 연결한다.')]),
 C('가 표지 아래에서는 어떻게 이야기하면 될까요?','작은 목소리로','가에 작은 목소리로 이야기하자고 적혀 있다.',[('큰 소리로','표지의 말과 반대이다.'),('말 대신 물만 마시며','나의 물잔 표지와 섞었다.')],P(1,'rule')),
 O('matching','말풍선 그림 / 물잔 그림을 각각 표지 가·나와 이으세요.','말풍선:가 / 물잔:나',[P(1,'rule'),P(2,'rule')],'한 쌍만 맞게 이음','두 그림을 바꿈'),
 O('explanation','가 표지를 본 친구에게 알맞은 행동을 한 문장으로 알려 주세요.','여기에서는 작은 목소리로 이야기하자.',P(1,'rule'),'작게라고만 말함','이야기는 절대로 하면 안 된다고 바꿈')],
 [panel('표지 가',('rule','작은 목소리로 이야기해요.','large',dict(icon='talk'))),panel('표지 나',('rule','이곳에서 물을 마셔요.','large',dict(icon='cup')))])
 E('plan-G1-media-01','S3','공은 어디에서 놀까',
 '가상 놀이집의 복도와 놀이방에 표지가 있어요. 민재는 공을 들고 복도에 서 있어요. 놀이방은 문 안쪽에 있어요.',
 '장소별 허용 범위를 구별한다. 공놀이가 가능한 장소를 찾되 놀이방 밖에서도 괜찮다거나 복도에 공을 들고만 있어도 안 된다고 확대하지 않는다.',[
 A('explanation','민재가 공놀이를 하려면 어디로 가야 하나요? 두 표지를 이어 설명하세요.','복도에서는 공을 던지지 말고 놀이방 안으로 가서 공놀이를 해야 한다.',[P(1,'rule'),P(2,'rule')],[D('장소 구별','복도와 놀이방 안을 구별한다.','놀이방만 말하고 복도와 구별하지 못한다.','복도와 놀이방을 같은 곳이라고 한다.'),D('행동·범위 연결','복도에서는 던지지 않고 놀이방 안에서 한다고 잇는다.','놀이방에서 한다고만 한다.','건물 어디서든 공을 던져도 된다고 한다.')]),
 C('공을 던지지 말라는 표지는 어디에 붙었나요?','복도','표지 가의 장소가 복도라고 적혀 있다.',[('놀이방 안','안에서 공놀이를 한다는 다른 표지이다.'),('놀이집 모든 곳','가에 적힌 복도라는 범위를 넓혔다.')],P(1,'rule')),
 O('explanation','두 표지의 말이 서로 반대라서 하나는 틀렸다고 할 수 있나요?','장소가 달라 함께 지킬 수 있다. 복도와 놀이방 안의 규칙이 다르다.',[P(1,'rule'),P(2,'rule')],'장소가 다르다고만 함','공놀이는 되거나 안 되거나 둘 중 하나만 가능하다고 함'),
 O('explanation','놀이방 밖 문 앞에서도 공을 던져도 된다는 말은 표지 나와 맞나요?','아니다. 표지는 놀이방 안에서만 공놀이를 하라고 했다.',P(2,'rule'),'안에서만이라는 범위를 설명하지 못함','놀이방 가까이에 있으면 모두 된다고 함')],
 [panel('표지 가 · 복도',('rule','복도에서는 공을 던지지 않아요.','large',dict(icon='no_ball'))),panel('표지 나 · 놀이방',('rule','놀이방 안에서만 공놀이를 해요.','large',dict(icon='ball')))])

 E('plan-G2-media-03','S3','활동표와 방 안내표',
 '가상 배움집의 두 표예요. 유나는 수요일 종이접기 활동에 가려고 해요. 요일과 활동을 먼저 찾고, 다른 표에서 그 활동의 방을 찾아보세요.',
 '한 표의 같은 행과 다른 표의 활동 이름을 연결한다. 시간 계산이나 실제 지도 이동 수행으로 집계하지 않는다.',[
 A('explanation','유나는 수요일 몇 시에 어느 방으로 가면 되나요? 두 표에서 찾은 정보를 함께 쓰세요.','수요일 오후 4시에 솔방으로 가면 된다. 활동표에서 종이접기의 시간을, 방 안내표에서 종이접기의 방을 찾았다.',[P(1,'wed'),P(2,'fold')],[D('행·열 대응','수요일 종이접기와 오후4시를 같은 행에서 연결한다.','활동이나 시간 중 하나만 맞힌다.','화요일 시간이나 다른 활동을 고른다.'),D('두 표 연결','종이접기를 연결 고리로 솔방을 찾는다.','솔방을 쓰지만 어느 활동의 방인지 잇지 못한다.','바느질의 달방으로 보낸다.')]),
 C('바느질을 하는 방은 어디인가요?','달방','방 안내표에서 바느질 행의 방 이름은 달방이다.',[('솔방','종이접기 활동의 방이다.'),('별방','흙놀이 활동의 방이다.')],P(2,'sew')),
 O('matching','화요일 / 목요일의 활동을 각각 쓰세요.','화요일:바느질 / 목요일:흙놀이',[P(1,'tue'),P(1,'thu')],'한 요일만 맞게 씀','두 활동을 바꿈'),
 O('explanation','활동표만 보면 방 이름까지 알 수 있나요?','활동표에는 요일·활동·시각만 있어 방 안내표도 보아야 한다.',[P(1,'head'),P(2,'head')],'다른 표도 본다고만 함','시간이 같으면 방도 같다고 함')],
 [panel('표 가 · 활동표',('head','요일 | 활동 | 시각','header'),('tue','화요일 | 바느질 | 오후 3시'),('wed','수요일 | 종이접기 | 오후 4시'),('thu','목요일 | 흙놀이 | 오후 4시'),kind='table'),panel('표 나 · 방 안내표',('head','활동 | 방','header'),('fold','종이접기 | 솔방'),('clay','흙놀이 | 별방'),('sew','바느질 | 달방'),kind='table')])
 E('plan-G2-media-03','S5','반납일을 잘못 읽은 쪽지',
 '가상 학급의 물건 대여표예요. 표 아래 설명에 미정은 아직 정하지 않았다는 뜻이라고 적혀 있어요.\n친구가 보낸 쪽지에는 세 사람 모두 금요일에 돌려주면 된다고 적혀 있어요. 표와 쪽지를 맞춰 보세요.',
 '각 행의 사람·물건·반납일을 보존한다. 미정은 금요일이나 반납할 필요 없음이라는 뜻이 아니다.',[
 A('explanation','친구의 쪽지를 표에 맞게 고치세요. 아직 정하지 않은 정보도 함께 남기세요.','태민은 돋보기를 화요일에, 수빈은 줄자를 금요일에 돌려준다. 나래의 자석 반납일은 아직 정하지 않아 확인해야 한다.',[P(1,'tae'),P(1,'su'),P(1,'na'),P(1,'note')],[D('정해진 날짜','태민 화요일·수빈 금요일을 사람과 연결한다.','한 사람의 날짜만 맞힌다.','두 사람 모두 금요일이라고 한다.'),D('미정 구별','나래의 반납일은 아직 모르므로 확인이 필요하다고 남긴다.','미정이라고만 옮기고 의미를 설명하지 못한다.','나래는 돌려줄 필요가 없다고 한다.')]),
 C('표에서 금요일로 정해진 사람은 누구인가요?','수빈','수빈 행의 반납일이 금요일이다.',[('태민','화요일로 적혀 있다.'),('나래','미정으로 적혀 있다.')],P(1,'su')),
 O('matching','태민 / 나래가 빌린 물건을 각각 쓰세요.','태민:돋보기 / 나래:자석',[P(1,'tae'),P(1,'na')],'하나의 물건만 맞게 씀','돋보기와 자석을 바꿈'),
 O('explanation','미정을 금요일로 바꾸어 쓰면 왜 안 되나요?','아직 정하지 않은 날짜를 이미 정한 것처럼 전달하게 되기 때문이다.',P(1,'note'),'날짜가 다르다고만 함','표에 빈 날짜가 있으면 다른 사람 날짜를 복사해도 된다고 함'),
 O('question_generation','나래에게 정확히 안내하려면 무엇을 더 확인해야 하나요?','나래가 자석을 언제까지 돌려줘야 하는지 확인해야 한다.',P(1,'na'),'더 물어본다고만 함','수빈의 날짜를 다시 물으면 나래 날짜도 정해진다고 함')],
 [panel('물건 대여표',('head','이름 | 빌린 물건 | 반납일','header'),('tae','태민 | 돋보기 | 화요일'),('su','수빈 | 줄자 | 금요일'),('na','나래 | 자석 | 미정'),('note','미정: 아직 정하지 않음','small'),kind='table')])
